-- Table structure for `schools`
CREATE TABLE IF NOT EXISTS `schools` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `name_mr` varchar(255) DEFAULT NULL,
  `address_line1` varchar(255) DEFAULT NULL,
  `address_line2` varchar(255) DEFAULT NULL,
  `village` varchar(100) DEFAULT NULL,
  `taluka` varchar(100) DEFAULT NULL,
  `district` varchar(100) DEFAULT NULL,
  `state` varchar(100) DEFAULT 'महाराष्ट्र',
  `pin_code` varchar(6) DEFAULT NULL,
  `udise_code` varchar(11) DEFAULT NULL,
  `email` varchar(255) NOT NULL,
  `phone` varchar(15) DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `logo` varchar(255) DEFAULT NULL,
  `plan_id` int(11) DEFAULT NULL,
  `custom_max_students` int(11) DEFAULT NULL,
  `subscription_start` date DEFAULT NULL,
  `subscription_end` date DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `working_days` int(11) DEFAULT 0,
  `working_days_monthly` text DEFAULT NULL COMMENT 'JSON: {"apr":22,"may":20,...} per-month working days',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `name_en` varchar(255) DEFAULT NULL,
  `website` varchar(255) DEFAULT NULL,
  `kendra` varchar(120) DEFAULT NULL,
  `beat` varchar(120) DEFAULT NULL,
  `management` varchar(120) DEFAULT NULL,
  `lower_class` int(11) DEFAULT 1,
  `upper_class` int(11) DEFAULT 12,
  `medium` varchar(60) DEFAULT NULL,
  `grant_type` varchar(60) DEFAULT NULL,
  `last_recognition_no` varchar(120) DEFAULT NULL,
  `school_code` varchar(60) DEFAULT NULL,
  `board_name` varchar(120) DEFAULT NULL,
  `board_affiliation_no` varchar(120) DEFAULT NULL,
  `sanstha` varchar(255) DEFAULT NULL,
  `established_date` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  KEY `plan_id` (`plan_id`),
  KEY `idx_schools_udise` (`udise_code`),
  KEY `idx_schools_phone` (`phone`),
  KEY `idx_schools_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `classes`
CREATE TABLE IF NOT EXISTS `classes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `school_id` int(11) NOT NULL,
  `std` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `section` varchar(255) NOT NULL,
  `class_teacher_id` int(11) DEFAULT NULL,
  `medium` varchar(40) DEFAULT 'मराठी',
  `stream` varchar(40) DEFAULT NULL,
  `academic_year_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_classes_lookup` (`school_id`,`std`,`section`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Table structure for `teachers`
CREATE TABLE IF NOT EXISTS `teachers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `school_id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `name_mr` varchar(255) DEFAULT NULL,
  `teacher_code` varchar(50) DEFAULT NULL,
  `email` varchar(255) DEFAULT NULL,
  `phone` varchar(15) DEFAULT NULL,
  `class_assigned` varchar(50) DEFAULT NULL,
  `section` varchar(10) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `role` varchar(30) DEFAULT 'teacher',
  PRIMARY KEY (`id`),
  KEY `idx_teachers_school_active` (`school_id`,`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table structure for `teacher_classes`
CREATE TABLE IF NOT EXISTS `teacher_classes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `school_id` int(11) NOT NULL DEFAULT 2,
  `teacher_id` int(11) NOT NULL,
  `class_id` int(11) NOT NULL,
  `std` tinyint(4) NOT NULL,
  `division` varchar(10) NOT NULL DEFAULT 'A',
  `academic_year` varchar(10) NOT NULL DEFAULT '2026-27',
  `is_class_teacher` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_teacher_class` (`teacher_id`,`class_id`,`division`,`academic_year`),
  KEY `idx_class_div` (`class_id`,`division`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

